def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if nr >= h or not (0 <= nc < w) or grid[nr][nc] != color:
                    continue

                # Continue the diagonal away from both ends of this pair.
                for rr, cc, sr, sc in (
                    (r - dr, c - dc, -dr, -dc),
                    (nr + dr, nc + dc, dr, dc),
                ):
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc

    return out
